-- ===== События сценариев =====
-- 1. Отключение света: Local Expres Москова работает на UPS
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID)
SELECT 'P2', s.ID, NULL, 'power', 'Отключение электроснабжения — магазин работает на UPS (осталось ~35% батареи)', 'open', 'agent', 'pw13a1'
FROM TBC_STORES s WHERE s.CODE = 'MD-CHS-013';
-- 2. Отключение света в Орхее: POS-02 выключился (UPS только на POS-01)
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID)
SELECT 'P3', s.ID, d.ID, 'power', 'POS-02 отключился при пропадании питания (не подключён к UPS)', 'ack', 'zabbix', 'pw201b'
FROM TBC_STORES s JOIN TBC_DEVICES d ON d.CODE = 'MD-ORH-201-POS-02' WHERE s.CODE = 'MD-ORH-201';
-- 3. Авария ISP: Foxi Бельцы без интернета → банковские POS и MEV подавлены как downstream
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID)
SELECT 'P2', s.ID, d.ID, 'isp', 'Интернет-канал StarNet недоступен (авария на линии), магазин в offline-режиме продаж', 'open', 'agent', 'isp102'
FROM TBC_STORES s JOIN TBC_DEVICES d ON d.CODE = 'MD-BLT-102-NET-01' WHERE s.CODE = 'MD-BLT-102';
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID, PARENT_EVENT_ID)
SELECT 'P3', s.ID, d.ID, 'bank_pos', 'Банковский POS-терминал не авторизует карты (нет связи с процессингом)', 'suppressed', 'correlation', 'isp102',
       (SELECT MAX(e.ID) FROM TBC_EVENTS e WHERE e.CORRELATION_ID = 'isp102' AND e.SERVICE_CODE = 'isp')
FROM TBC_STORES s JOIN TBC_DEVICES d ON d.CODE = 'MD-BLT-102-POS-01' WHERE s.CODE = 'MD-BLT-102';
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID, PARENT_EVENT_ID)
SELECT 'P3', s.ID, d.ID, 'mev', 'MEV: чеки не отправляются в SFS (offline-очередь растёт)', 'suppressed', 'correlation', 'isp102',
       (SELECT MAX(e.ID) FROM TBC_EVENTS e WHERE e.CORRELATION_ID = 'isp102' AND e.SERVICE_CODE = 'isp')
FROM TBC_STORES s JOIN TBC_DEVICES d ON d.CODE = 'MD-BLT-102-POS-01' WHERE s.CODE = 'MD-BLT-102';
-- 4. Сбой хоста банка: Bonus Дачия, интернет в норме
INSERT INTO TBC_EVENTS (SEVERITY, STORE_ID, DEVICE_ID, SERVICE_CODE, PROBLEM, STATUS, SOURCE, CORRELATION_ID)
SELECT 'P2', s.ID, NULL, 'bank_pos', 'Банковские терминалы Victoriabank: отказ авторизации на всех кассах (интернет в норме — проблема на стороне банка)', 'ack', 'agent', 'bnk010'
FROM TBC_STORES s WHERE s.CODE = 'MD-CHS-010';
-- 5. Деградация MEV (SFS) по всей сети
