-- ===== Действия персонала =====
-- Ненужные перезагрузки: кассир Bonus Дачия трижды перезагрузил POS-02 при сбое банка
INSERT INTO TBC_ACTIONS (STORE_ID, DEVICE_ID, EVENT_ID, ACTION_TYPE, PERFORMED_BY, NOTE, IS_JUSTIFIED, RESULT, STARTED_AT, FINISHED_AT)
SELECT s.ID, d.ID, (SELECT MAX(ID) FROM TBC_EVENTS WHERE CORRELATION_ID = 'bnk010'), 'restart_pos', 'кассир М.Руссу', 'Перезагрузка кассы «не проходит карта» — причина была на стороне банка', 'N', 'no_effect', SYSTIMESTAMP - INTERVAL '52' MINUTE, SYSTIMESTAMP - INTERVAL '49' MINUTE
FROM TBC_STORES s JOIN TBC_DEVICES d ON d.CODE = 'MD-CHS-010-POS-02' WHERE s.CODE = 'MD-CHS-010';
