-- ===== Очереди на кассах (metric queue_len, scope app, чел. в очереди) =====
-- Все POS/SCO сети, 7 дней почасово. Пики обед/вечер. В магазине MD-CHS-001
-- SCO-02 не работает — очереди заметно длиннее (польза мониторинга очередей).
INSERT INTO TBC_METRIC_SAMPLES (DEVICE_ID, SCOPE, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT d.ID, 'app', 'queue_len',
       GREATEST(0, ROUND(
         (CASE WHEN s.CODE = 'MD-CHS-001' THEN 4.5 ELSE 1.5 END)
         + 3 * ABS(SIN((MOD(h.LVL, 24) - 5) / 2.5))
         + DBMS_RANDOM.VALUE(0, 2))),
       SYSTIMESTAMP - NUMTODSINTERVAL(h.LVL, 'HOUR')
FROM (SELECT LEVEL AS LVL FROM DUAL CONNECT BY LEVEL <= 168) h
CROSS JOIN TBC_DEVICES d
JOIN TBC_STORES s ON s.ID = d.STORE_ID
WHERE d.DEVICE_TYPE IN ('POS', 'SCO') AND d.STATUS <> 'offline';

-- ===== Климат / питание / UPS =====
-- Жара: Super Bonus, воздух на улице до +38
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-011'), 'temp_air', ROUND(28 + 10 * ABS(SIN((MOD(LEVEL, 24) - 3) / 7)) + DBMS_RANDOM.VALUE(0, 1), 1), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;
-- Серверная Super Bonus: рост 26 → 34
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-011'), 'temp_server_room', ROUND(34 - LEVEL / 6.0, 1), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;
-- Напряжение сети Super Bonus: просадки до 198V
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-011'), 'grid_voltage', ROUND(218 - 12 * ABS(SIN(LEVEL / 3)) - DBMS_RANDOM.VALUE(0, 8)), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;
-- Центральная серверная (узел CENTRAL-01): температура растёт 24 → 30, UPS-нагрузка ~78%
INSERT INTO TBC_ENV_SAMPLES (NODE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_NODES WHERE CODE = 'CENTRAL-01'), 'temp_server_room', ROUND(30 - LEVEL / 8.0, 1), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;
INSERT INTO TBC_ENV_SAMPLES (NODE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_NODES WHERE CODE = 'CENTRAL-01'), 'ups_load_pct', ROUND(60 + 18 * ABS(SIN(LEVEL / 9)) + DBMS_RANDOM.VALUE(0, 4)), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;
-- Отключение света Local Expres: разряд батареи UPS 100% → 35% за последние ~80 минут
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-013'), 'ups_battery_pct', 100 - (9 - LEVEL) * 8, SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL * 10, 'MINUTE') FROM DUAL CONNECT BY LEVEL <= 9;
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-013'), 'on_ups', 1, SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL * 10, 'MINUTE') FROM DUAL CONNECT BY LEVEL <= 9;
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-CHS-013'), 'ups_runtime_min', GREATEST(5, 90 - (9 - LEVEL) * 9), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL * 10, 'MINUTE') FROM DUAL CONNECT BY LEVEL <= 9;
-- Мороз в Орхее: до -18 ночью
INSERT INTO TBC_ENV_SAMPLES (STORE_ID, METRIC, NUM_VALUE, SAMPLED_AT)
SELECT (SELECT ID FROM TBC_STORES WHERE CODE = 'MD-ORH-201'), 'temp_air', ROUND(-10 - 8 * ABS(SIN((MOD(LEVEL, 24) - 16) / 7)), 1), SYSTIMESTAMP - NUMTODSINTERVAL(LEVEL, 'HOUR') FROM DUAL CONNECT BY LEVEL <= 48;

COMMIT;
